local UIWorldBossFormationDialog = Class("UIWorldBossFormationDialog")

function UIWorldBossFormationDialog:__init() 
    self._curLevelId = nil               --关卡id
    self._curLevelType = nil             
    self._teamNums = 1                   --队伍数量  默认只有一个
end

function UIWorldBossFormationDialog:__delete()
    self._curLevelId = nil               
    self._curLevelType = nil               
end

function UIWorldBossFormationDialog:Awake()
    SetButtonAction(self.ButClose, Bind(self, self.OnBtnClose))
    SetButtonAction(self.BtnUpBuff, Bind(self, self.OnBtnUpBuff))

    self.EventRefeshTeamMember = Events.AddListener(Constants.EventNames.RefeshTeamMember, Bind(self, self.OnRefeshTeamMember))
    self.EventSkillCompoundChange = Events.AddListener(Constants.EventNames.SkillCompoundChange, Bind(self, self.OnSkillCompoundChange))

    local argument = self.controller.Argument.parameters
    if not argument then
        return
    end

    self._curLevelId = checkNumber(argument.levelId)    -- 关卡ID
    if self._curLevelId == 0 then
        return
    end

    self._curLevelType = GoodsUtils.GetIdType(self._curLevelId, Constants.IDArea.Quests)     --关卡类型
    if self._curLevelType == Constants.IDType.None then
        return
    end

    self._curBossPlanId = worldBossComponent:GetCurBossPlanId()
    if not self._curBossPlanId then
        return
    end

    self._curBossPlanVo = QuestConfMgr:GetInstance():GetWorldBossPlanVo(self._curBossPlanId)
    if not self._curBossPlanVo then
        return
    end
    CfUtils.FillImage(self.controller.gameObject.transform:Find("BgGroup/ImgBg"), self._curBossPlanVo.modelId)

    self._teamNums = QuestConfMgr:GetInstance():GetQuestTeamNum(self._curLevelId)
    self:FillTeams()

    SetButtonAction(self.BtnOneKeyTeamSetting, Bind(self, self.OnBtnOneKeyTeamSetting))
    SetButtonAction(self.BtnFight, Bind(self, self.OnBtnFight))

    CfUtils.SetActive(self.BtnAutoFight, true)
end

--自动战斗
function UIWorldBossFormationDialog:OnBtnAutoFight()
    local isUnlock = GameUtils.IsUnlockedSingle(Constants.CommonUnlockType.PassQuest, tostring(Constants.UNLOCK_PLAYERSETTING_QUESTID))
    if not isUnlock then
        GameUtils.Toast(localize("自动战斗未解锁"))
        return
    end
    local isAuto = QuestConfMgr:GetInstance():IsAutoBattle()
    QuestConfMgr:GetInstance():SetAutoBattle(not isAuto)

    isAuto = QuestConfMgr:GetInstance():IsAutoBattle()
    CfUtils.PlayAnimator(self.BtnAutoFight.transform:Find("AnimRoot"), isAuto and "OFF-ON" or "ON-OFF")
end

--绘制所有的队伍
function UIWorldBossFormationDialog:FillTeams()
    self._allTeamPosInfoGo = {}
    for i = 1, self._teamNums do
        local go = self["UITeamInfoNode"..i]
        table.insert(self._allTeamPosInfoGo, {
            teamIndex = i,
            go = go,
            pos = go.transform.localPosition
        })
        self:FillTeam(go, i)
    end

    for k, v in pairs(self._allTeamPosInfoGo) do
        local scr = CfUtils.GetLuaScr(v.go, UITeamInfoNode)
        if scr then
            scr:InitChangePosInfo(self._allTeamPosInfoGo, function()
                self:FillTeams()
            end)
        end
    end
end

--绘制一条队伍信息
function UIWorldBossFormationDialog:FillTeam(go, teamIndex)
    local scr = CfUtils.GetLuaScr(go, UITeamInfoNode)
    if scr then
        local data = teamComponent:GetTeamInfoByQuestId(self._curLevelId, teamIndex)
        scr:Refresh(data, self._curLevelId, teamIndex)
    end
end

--一键编队
function UIWorldBossFormationDialog:OnBtnOneKeyTeamSetting()
    self:GetAutoTeamTab()
end

--自动编队
function UIWorldBossFormationDialog:GetAutoTeamTab()
    --取得所有卡牌
    local cards = self:GetAllCardsData()
    local t = CardUtils.SortCardBySortType(cards, Constants.SortType.CombatPower, true)
    local teamNum = QuestConfMgr:GetInstance():GetQuestTeamNum(self._curLevelId)
        
    local cardIndex = 1   --选人的下标
    local teamInfo = {}
    for i = 1, teamNum do
        local isUnlock, err = QuestConfMgr:GetInstance():IsUnlockTeamByIndex(i)
        if isUnlock then
            local memberNum = teamComponent:GetMaxSelectNum(self._curLevelId, Constants.ChooseCardStatus.Normal, i) --初始空位数量
            teamInfo[i] = {
                cardsInfo = {}
            }
            if cardIndex <= table.count(t) then
                local count = 0
                for _ind = cardIndex, table.count(t) do
                    local cardData = t[_ind]
                    --添加到编队中
                    local refId = cardData.id
                    local type = Constants.TeamMemberType.PlayerCard
                    table.insert(teamInfo[i].cardsInfo, CfUtils.GetTeamMemberDojo{
                        type = type,
                        refId = refId
                    })
                    count = count + 1 
                    cardIndex = cardIndex + 1
                    if count >= memberNum then
                        break
                    end
                end
                if count < memberNum then
                    for j = count + 1, memberNum do
                        table.insert(teamInfo[i].cardsInfo, {})
                    end
                end
            else
                for j = 1, memberNum do
                    table.insert(teamInfo[i].cardsInfo, {})
                end
            end
        end
    end
    for i = 1, teamNum do
        local isUnlock, err = QuestConfMgr:GetInstance():IsUnlockTeamByIndex(i)
        if isUnlock then
            teamComponent:SetTeamByQuestId(self._curLevelId, teamInfo[i].cardsInfo, nil, i)
        end
    end
end

--根据当前的关卡类型获取所有的卡牌信息
function UIWorldBossFormationDialog:GetAllCardsData(type)
    local cards = cardComponent:GetAllCardTable()
    return cards
end

--刷新队伍成员
function UIWorldBossFormationDialog:OnRefeshTeamMember(body)
    self:FillTeams()
end

function UIWorldBossFormationDialog:OnBtnClose()
    UIModule.BackDialog()
end

function UIWorldBossFormationDialog:OnBtnUpBuff()
    local id = worldBossComponent:GetCurBossPlanId()
    self._curBossPlanVo = QuestConfMgr:GetInstance():GetWorldBossPlanVo(id)
    local t = QuestConfMgr:GetInstance():GetWorldBossUpData(self._curBossPlanVo.UpGroup)
    UIModule.OpenDialog({ id = Constants.UITypeIds.UIBuffUpDialog, parameters = {buffData = t}})
end

--开始战斗
function UIWorldBossFormationDialog:OnBtnFight()
    local isCanBattle, errStr = self:IsCanBattle()
    if not isCanBattle then
        GameUtils.Toast(errStr)
        return
    end

    GameUtils.Request(Interfaces.WorldBossClearCurrentQuest, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        teamComponent:SetTeamReq(self._curLevelId, function()
            cs_coroutine.start(function()
                self.controller:SetBackArgument(true)
                local worldBossComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.WorldBossComponent)
                worldBossComponent:WorldBossBattleBeging(self._curLevelId)
            end)
        end)
    end)
end

--是否可以战斗
function UIWorldBossFormationDialog:IsCanBattle()
    local isHaveMember = false
    local err = localize("队伍不能为空")
    for i = 1, self._teamNums do
        local t = teamComponent:GetTeamByQuestId(self._curLevelId, i)
        local count = teamComponent:GetTeamMemberCount(t) 
        if count > 0 then
            isHaveMember = true
            break
        end
    end
    return isHaveMember, err
end

