        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.1))
        local effectBg = self.controller.gameObject:GetComponent(typeof(UIEffectCapturedImage))
        effectBg:Capture()
    end)
end

function UIWorldBossFormationDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if not isNull(self) then
            if self._co then
                cs_coroutine.stop(self._co)
                self._co = nil
            end
            Events.RemoveListener(Constants.EventNames.SkillCompoundChange, self.EventSkillCompoundChange)
            Events.RemoveListener(Constants.EventNames.RefeshTeamMember, self.EventRefeshTeamMember)
        end
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIWorldBossFormationDialog
